import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Handle } from 'reactflow';
import { NODE_COLORS } from './BaseNode'; // Import the color mapping

export const TextNode = ({ data, id }) => {
  const [text, setText] = useState(data.text || '');
  const textareaRef = useRef(null);
  const colors = NODE_COLORS.text || NODE_COLORS.custom;

  // Auto-resize the textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.max(textareaRef.current.scrollHeight, 60) + 'px';
    }
  }, [text]);

  // Extract variables from text
  const variables = useMemo(() => {
    const matches = text.match(/{{\s*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*}}/g) || [];
    return [...new Set(matches.map(v => v.slice(2, -2).trim()))];
  }, [text]);

  return (
    <div
      style={{
        width: '220px',
        borderRadius: '8px',
        border: `1px solid ${colors.header}`,
        backgroundColor: colors.bg,
        boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
        fontFamily: "'Inter', sans-serif",
      }}
    >
      <div
        style={{
          padding: '8px 12px',
          backgroundColor: colors.header,
          color: 'white',
          fontSize: '13px',
          fontWeight: 600,
          borderBottom: `1px solid ${colors.header}`,
        }}
      >
        TEXT
      </div>
      <div style={{ padding: '10px 12px', fontSize: '13px', color: '#374151' }}>
        <textarea
          ref={textareaRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Enter text... Use {{variable}} for inputs"
          style={{
            width: '100%',
            padding: '6px',
            border: `1px solid ${colors.header}`,
            borderRadius: '4px',
            fontSize: '12px',
            resize: 'none',
            overflow: 'hidden',
            minHeight: '60px',
          }}
        />
        {variables.length > 0 && (
          <div style={{ marginTop: '8px', fontSize: '11px', color: '#6b7280' }}>
            Variables: {variables.map(v => <span key={v} style={{ marginRight: '4px', padding: '2px 4px', backgroundColor: colors.header, color: 'white', borderRadius: '3px' }}>{v}</span>)}
          </div>
        )}
      </div>
      {/* Target handles for variables */}
      {variables.map((variable, index) => (
        <Handle
          key={variable}
          type="target"
          position="left"
          id={variable}
          style={{
            top: `${30 + index * 25}px`,
            width: '12px',
            height: '12px',
            background: colors.header,
            border: '2px solid white',
          }}
        />
      ))}
      {/* Source handle for output */}
      <Handle
        type="source"
        position="right"
        id="output"
        style={{
          top: '50%',
          width: '12px',
          height: '12px',
          background: colors.header,
          border: '2px solid white',
        }}
      />
    </div>
  );
};
